# =====================================================================
#  ecommerce.map - phishing phrases for online shops and retail
#  Part of: phishing-detector by Develust Technology
#
#  Format : one regex per line, /pattern/flags (i = case-insensitive,
#           u = UTF-8). No trailing spaces.
#  Note   : PHISH_TEXT scores 0 alone; it only adds points together
#           with a phishing link (PHISH_URL / PHISHING).
#
#  Themes : marketplace seller account suspension (Amazon, eBay, Etsy,
#           Shopify, Trendyol, Hepsiburada, Wildberries, Ozon,
#           AliExpress, Mercado Libre, Allegro, Flipkart), payment
#           gateway limits (PayPal, Stripe), chargebacks and disputes,
#           listing removal, intellectual-property / copyright
#           complaints, fake customer complaints with "photos",
#           store payment failures
#
#  Avoided: order confirmations, "your order has shipped", "new order
#           received", "price list attached", because shops send and
#           receive real ones every day.
# =====================================================================

# ===== English =====
# Seller accounts
/your\s+(seller|merchant|vendor|store|shop)\s+account\s+(has\s+been|will\s+be|is)\s+(suspended|deactivated|restricted|on\s+hold|under\s+review|closed)/i
/(amazon|seller\s+central|ebay|etsy|shopify|trendyol|hepsiburada|wildberries|ozon|aliexpress|mercado\s+libre|allegro|flipkart)\s+(seller\s+|merchant\s+)?(account\s+)?(suspended|deactivated|verification\s+required|action\s+required|policy\s+violation)/i
/(reactivate|reinstate|restore)\s+your\s+(seller|merchant|store|selling)\s+(account|privileges)/i
/(your\s+)?(listings?|products?)\s+(has\s+been|have\s+been|will\s+be)\s+(removed|deactivated|suppressed|blocked)\s+(due\s+to|for)/i
# Payment gateways
/your\s+(paypal|stripe|payoneer|wise)\s+account\s+(has\s+been|is)\s+(limited|restricted|suspended|on\s+hold)/i
/(payouts?|withdrawals?|disbursements?)\s+(are\s+|is\s+|have\s+been\s+)?(on\s+hold|paused|suspended|frozen)/i
/(resolve|remove)\s+(the\s+)?(account\s+)?limitation/i
# Chargebacks / disputes
/(a\s+)?(chargeback|dispute|claim)\s+(has\s+been\s+)?(opened|filed|raised)\s+(against|on|for)\s+(your\s+)?(order|transaction|payment)/i
/respond\s+to\s+(the\s+)?(chargeback|dispute|claim)\s+within\s+\d+/i
# IP / copyright complaints
/(intellectual\s+property|copyright|trademark)\s+(infringement|violation)\s+(complaint|notice|report)/i
/(report|notice)\s+of\s+(alleged\s+)?(intellectual\s+property|copyright|trademark)\s+infringement/i
# Fake customer complaints
/(customer|buyer)\s+(complaint|claim)\s+(about|regarding)\s+(your\s+)?(product|order|item)/i
/(see|view|check)\s+(the\s+)?(photos?|pictures?|images?|video)\s+of\s+the\s+(damaged|defective|wrong|broken)\s+(product|item|order)/i
/(the\s+)?(product|item)\s+(i\s+)?(received|bought|ordered)\s+(is|was)\s+(damaged|defective|broken|fake|counterfeit)[^.]{0,40}(see|view|photos?|link)/i
# Store / platform payments
/(store|shop|subscription)\s+payment\s+(failed|declined|unsuccessful)/i
/your\s+(store|shop)\s+will\s+be\s+(closed|paused|deactivated)\s+(unless|if|within)/i

